export const glacierViews2={
 'glacier-valley':[['trough','Widen & deepen'],['spurs','Truncate spurs'],['hanging','Hanging tributary'],['lake','After ice: lake']],
 'glacier-roche':[['forward','Ice →'],['plucking','Lee-side plucking'],['reverse','Ice ←'],['form','Exposed bedrock']],
 'glacier-moraine':[['ground','Ground moraine'],['terminal','Terminal ridge'],['retreat','Retreat & pauses']],
 'glacier-streamlined':[['crag','Crag-and-tail'],['drumlin','Streamlined sediment'],['field','Drumlin field'],['compare','Compare forms']],
 'glacier-landuse':[['farm','Compacted pasture'],['woodland','Established woodland'],['harvest','Harvest & tracks'],['town','Settlement & drains']]
};
export const glacierRequirements2=Object.fromEntries(Object.entries(glacierViews2).map(([k,v])=>[k,v.map(x=>x[0])]));
export const glacierAnimated2=(k,v)=>!((k==='glacier-valley'&&v==='lake')||(k==='glacier-roche'&&v==='form')||(k==='glacier-streamlined'&&['field','compare'].includes(v)));
const tx=(x,y,s,z=13)=>`<text x="${x}" y="${y}" font-size="${z}">${s}</text>`;
const ln=(p,c='#b9dfe8',w=3,rest='')=>`<path d="${p}" stroke="${c}" stroke-width="${w}" fill="none" ${rest}/>`;
const ar=(x,y,a,b)=>ln(`M${x} ${y}L${a} ${b}`,'#f0a28e',3,'marker-end="url(#g2Arrow)"');
const dot=(x,y,r=5,c='#eac79e')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
const wrap=(b,c)=>`<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${c.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><linearGradient id="g2Rock" x2="0" y2="1"><stop stop-color="#adb4a1"/><stop offset="1" stop-color="#758b81"/></linearGradient><linearGradient id="g2Ice" x2="0" y2="1"><stop stop-color="#d7edf0"/><stop offset="1" stop-color="#78a8bb"/></linearGradient><marker id="g2Arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5 0 10Z" fill="#f0a28e"/></marker></defs><g font-family="sans-serif" fill="#edf2ef">${b}</g></svg><p class="geo-caption">${c}</p>`;
export function glacierScene2(k,selected,t=0){const opts=glacierViews2[k];if(!opts)return '';const v=opts.some(x=>x[0]===selected)?selected:opts[0][0];t=Math.min(1,Math.max(0,Number(t)||0));if(!glacierAnimated2(k,v))t=0;let b='',c='';
 if(k==='glacier-valley'){
  if(v==='trough'){const w=105+t*60,d=250+t*35;b=tx(25,30,'CROSS-SECTION · original river valley dashed')+`<path d="M20 80L${220-w} 160Q${220-w} ${d} 220 ${d}T${220+w} 160L420 80V325H20Z" fill="url(#g2Rock)"/>`+ln('M20 80L220 250 420 80','#edd2b8',2,'stroke-dasharray="6 5"')+`<path d="M${220-w} 160Q${220-w} ${d} 220 ${d}T${220+w} 160Z" fill="url(#g2Ice)"/>`+ar(160,135,120,145)+ar(280,135,320,145)+ar(220,180,220,235)+tx(25,315,'Abrasion + plucking · wider / deeper',13);c='Ice erodes sides and floor, widening and deepening a former river valley into a trough. Dashed profile is the earlier conceptual valley, not a survey; real trough shapes vary and time is compressed.';}
  if(v==='spurs'){const tip=255-t*75;b=tx(25,30,'PLAN VIEW · ice travels down the valley ↓')+`<path d="M20 65H115L${tip} 120 115 170 ${tip} 235 115 295H20Z" fill="url(#g2Rock)"/><path d="M420 65H325L${440-tip} 180 325 225 ${440-tip} 290H420Z" fill="url(#g2Rock)"/>`+`<path d="M180 65H260V310H180Z" fill="url(#g2Ice)" opacity=".75"/>`+ar(220,80,220,270)+tx(25,335,'Projecting ridge ends are cut back',12);c='Glacial erosion cuts across projecting spurs, leaving truncated ends along a straighter valley. This is a schematic plan, not an OS contour map; translucent ice shows the valley corridor.';}
  if(v==='hanging'){b=tx(25,30,'AFTER ICE · unequal depths remain')+'<path d="M20 80L100 155H215V265H350L420 120V325H20Z" fill="url(#g2Rock)"/>'+ln('M25 147H210V262H350','#a6d6e6',8)+tx(25,115,'Tributary floor',13)+tx(255,240,'Main trough',13)+ar(370,190,370,260);for(let i=0;i<8;i++)b+=dot(214,160+(t*95+i*14)%100,3,'#e0edf0');c='The main glacier excavates more deeply than a tributary, leaving its floor hanging above the main trough. The animated stream descends the inherited step; it does not create the original depth difference in one replay.';}
  if(v==='lake'){b=tx(25,30,'LONGITUDINAL SECTION · basin after ice loss')+'<path d="M20 145Q100 190 150 260T305 205L330 160 420 200V325H20Z" fill="url(#g2Rock)"/><path d="M85 190H316L305 205Q240 300 150 260Q110 220 85 190Z" fill="#83b3c3"/>'+tx(145,170,'Retained lake',15)+ar(365,105,331,158)+tx(320,80,'Rock bar',12);c='Over-deepening can leave a basin that holds a glacial lake behind a rock or sediment threshold. Water retention and later erosion or infilling matter. The still shows structure, not measured lake depth or current conditions.';}
 }
 if(k==='glacier-roche'){
  const reverse=v==='reverse',display=v==='form';b=tx(25,30,'SIDE VIEW · asymmetric bedrock obstacle');let body='<path d="M25 270Q100 270 155 210T255 165L285 190 278 218 307 225 310 270H420V325H25Z" fill="url(#g2Rock)"/>';
  if(!display){body+='<path d="M25 105H420V270H310L307 225 278 218 285 190 255 165Q195 160 155 210T25 270Z" fill="url(#g2Ice)" opacity=".8"/>'+ar(65,80,360,80);if(v==='plucking')body+=`<path d="M${280+t*65} ${195-t*15}l20 3 2 20-20-3Z" fill="#e2ba91"/>`;else body+=dot(55+t*290,260-Math.sin(t*Math.PI)*95,5);}
  if(reverse)body=`<g transform="translate(440 0) scale(-1 1)">${body}</g>`;
  b+=body+tx(reverse?250:25,125,'Gentler stoss',12)+tx(reverse?25:280,145,'Steeper lee',12)+tx(25,315,display?'Abraded face → plucked face · bedrock remains':reverse?'Flow ← · labels follow direction':'Flow → · labels follow direction',13);c=display?'Typical roche moutonnée: a gentler abraded stoss face and a steeper plucked lee face in remaining bedrock. Corroborate shape-based direction with striations and surrounding evidence.':v==='plucking'?'A jointed block detaches from the lee face and moving ice removes it. Basal conditions and rock structure affect plucking; the exaggerated step and timing are not a measurement.':reverse?'Reversed ice direction: the gentler abraded stoss side is now on the right and the steeper plucked lee side on the left. Up-ice and down-ice are flow-relative, not fixed page positions.':'Ice and basal debris cross the gentler stoss face towards the steeper lee face. Abrasion smooths the up-ice side; plucking affects the lee. Shape and debris path are simplified.';
 }
 if(k==='glacier-moraine'){
  const edge=v==='retreat'?330-t*160:310;b=tx(25,30,'SIDE VIEW · mixed sediment is left behind')+'<path d="M20 285H420V325H20Z" fill="url(#g2Rock)"/>'+`<path d="M20 90L${edge-60} 180Q${edge} 205 ${edge} 285H20Z" fill="url(#g2Ice)"/>`+ar(50,120,170,160);
  if(v==='ground'){b+=ln('M35 286H390','#d6ba95',12);for(let i=0;i<10;i++)b+=dot(40+i*34,280-(i%3)*3,2+i%4);b+=dot(100+t*170,240+t*40,5)+tx(25,315,'Ground moraine: spread beneath former ice',12);c='A spread of mixed debris deposited beneath ice can form ground moraine. Symbolic mixed grain sizes illustrate poorly sorted till; meltwater-reworked sediment may differ.';}
  else{const ridges=v==='retreat'?[335,280,225]:[325];for(const x of ridges.filter(x=>v!=='retreat'||x>=edge+5))b+=`<path d="M${x-20} 285L${x} ${v==='terminal'?285-t*55:240} ${x+20} 285Z" fill="#d6ba95"/>`;for(let i=0;i<4;i++)b+=dot(edge+5+t*12,240+t*40+i*3,3+i%2);b+=tx(25,315,v==='terminal'?'Debris accumulates at a former outer margin':'Outer terminal ridge · later retreat-pause ridges',12);c=v==='terminal'?'Debris released, dumped or pushed at the ice end can accumulate as a terminal ridge at the outer limit of an advance. A stable margin can receive flowing ice and debris; formation mechanisms vary.':'As a margin retreats, pauses can leave recessional ridges within its former outer terminal limit. Ice still flows downslope. These schematic positions do not provide dates, distances or retreat speeds.';}
 }
 if(k==='glacier-streamlined'){
  if(v==='field'){b=tx(25,30,'PLAN VIEW · long axes share an alignment');for(let i=0;i<9;i++){const x=40+i%3*125,y=70+Math.floor(i/3)*75;b+=`<path d="M${x} ${y+20}Q${x} ${y-3} ${x+22} ${y+2}Q${x+60} ${y+7} ${x+95} ${y+20}Q${x+20} ${y+44} ${x} ${y+20}Z" fill="#b7b393"/>`;}b+=tx(25,325,'Alignment ≠ precise age, speed or complete history',12);c='A drumlin field can preserve a broad flow alignment. Head-to-tail shape and corroborating evidence help infer direction; long axes alone do not provide a complete history or exact speed.';}
  else if(v==='compare'){b=tx(25,30,'SIDE VIEW · do not swap the typical shapes')+ar(50,65,350,65)+'<path d="M30 155Q100 155 155 105L180 135 175 155H405" fill="#a9b4aa"/>'+tx(215,130,'Roche: bedrock',13)+'<path d="M30 275Q40 205 95 220Q205 235 405 275Z" fill="#d4ba96"/>'+tx(215,235,'Drumlin: often sediment',13)+tx(25,325,'Typical forms · composition and context matter',12);c='Typical roche moutonnée: gentler abraded up-ice face, steeper plucked lee. Typical drumlin: blunter up-ice head, longer tapered down-ice tail; commonly sediment, sometimes with a rock core.';}
  else{const crag=v==='crag',end=crag?210+t*180:220+t*170;b=tx(25,30,'SIDE VIEW · ice moves →')+ar(40,75,360,75)+'<rect x="20" y="110" width="400" height="110" fill="url(#g2Ice)" opacity=".65"/><path d="M20 285H420V325H20Z" fill="url(#g2Rock)"/>';
   b+=crag?`<path d="M90 285L105 170H145L170 225L${end} 285Z" fill="#d4ba96"/><path d="M90 285L105 170H145L170 285Z" fill="#9da99f"/>`:`<path d="M40 285Q45 205 110 215Q190 225 ${end} 285Z" fill="#d4ba96"/>`;b+=dot(40+t*350,135,5)+tx(25,315,crag?'Resistant crag · sheltered down-ice tail':'Blunt head · tapered tail · variable internal structure',12);c=crag?'A resistant bedrock crag shelters its down-ice area; a tail of more erodible rock and/or sediment can be preserved or deposited. This conceptual change is not the actual growth history of a named crag.':'Moving ice can erode, deposit and deform subglacial sediment into streamlined hills. This animation illustrates moulding only: no single universal drumlin-formation mechanism is claimed.';}
 }
 if(k==='glacier-landuse'){
  b=tx(25,30,'CONTROLLED CONCEPT · compare land cover')+'<path d="M20 140L320 275H420V325H20Z" fill="url(#g2Rock)"/><path d="M320 275H420V295H320Z" fill="#83b1c1"/>';
  if(v==='woodland'){for(let i=0;i<5;i++)b+=`<path d="M${50+i*48} ${137+i*21}v-32m-12 22l12-22 12 22Z" stroke="#c2d7b7" stroke-width="3" fill="#94b69f"/>`;for(let i=0;i<5;i++)b+=dot(70+i*47,155+i*21+t*35,3,'#b8dce7');c='Established, well-designed woodland can intercept rain, support infiltration and stabilise soil. Actual effects depend on place and management; tree cover does not guarantee the absence of floods.';}
  else{if(v==='farm')b+=ln('M25 142L305 267','#d1bc96',10)+tx(25,92,'Compaction / reduced vegetation',13);if(v==='harvest')b+=ln('M25 147L305 272','#d1bc96',12)+tx(25,92,'Harvesting / tracks / drainage',13);if(v==='town'){for(let i=0;i<4;i++)b+=`<rect x="${45+i*55}" y="${105+i*25}" width="35" height="30" rx="3" fill="#d4c2af"/>`;b+=ln('M35 150L315 276','#e2d7cc',7)+tx(25,80,'Hard surfaces + connected drains',13);}for(let i=0;i<6;i++){const x=40+(t*260+i*40)%270;b+=dot(x,150+(x-40)*.44,3,'#d6e8ee');}c=v==='farm'?'Compaction and loss of vegetation can reduce infiltration and increase quick runoff or erosion. Stocking, soil, slope and antecedent wetness change the response. This is not a universal result for farming.':v==='harvest'?'Poorly managed harvesting, access roads and drainage can disturb soil and increase runoff or sediment delivery. Compare these operations with established woodland rather than treating forestry as one fixed state.':'Roofs, roads and connected drains can speed runoff delivery. Excavation, loading and changed drainage can affect slope stability. The model gives mechanisms, not a mapped settlement or a prediction of slope failure.';}
  for(let i=0;i<10;i++)b+=ln(`M${35+i*32} ${55+(t*70+i*8)%70}l-3 9`,'#b8dce7',2);b+=tx(25,318,'No measured runoff quantities or OS/GIS layers',12);
 }
 return wrap(b,c);
}
